import Foundation

// MARK: - Equipment + muscle groups

/// Equipment an exercise needs. A generated program only picks exercises
/// whose equipment is a subset of what the user has.
enum Equipment: String, Codable, CaseIterable, Hashable {
    case barbell
    case dumbbell
    case cable
    case machine
    case bench
    case bodyweight
    case bands
    case kettlebell
    case smithMachine
    case ezBar
    case trapBar
    case landmine
    case suspension
    case medicineBall
    case squatRack
    case pullUpBar
    case weightPlates

    var label: String {
        switch self {
        case .barbell: return "Barbell"
        case .dumbbell: return "Dumbbells"
        case .cable: return "Cable"
        case .machine: return "Machine"
        case .bench: return "Bench"
        case .bodyweight: return "Bodyweight"
        case .bands: return "Bands"
        case .kettlebell: return "Kettlebell"
        case .smithMachine: return "Smith Machine"
        case .ezBar: return "EZ Bar"
        case .trapBar: return "Trap Bar"
        case .landmine: return "Landmine"
        case .suspension: return "Suspension (TRX)"
        case .medicineBall: return "Medicine Ball"
        case .squatRack: return "Squat Rack"
        case .pullUpBar: return "Pull-Up Bar"
        case .weightPlates: return "Weight Plates"
        }
    }
}

enum MuscleGroup: String, Codable, CaseIterable {
    case chest
    case back
    case shoulders
    case biceps
    case triceps
    case forearms
    case quads
    case hamstrings
    case glutes
    case calves
    case core
    case obliques
    case neck
    case wrists
    case feet
    case ankles
    case fullBody

    var label: String {
        switch self {
        case .chest: return "Chest"
        case .back: return "Back"
        case .shoulders: return "Shoulders"
        case .biceps: return "Biceps"
        case .triceps: return "Triceps"
        case .forearms: return "Forearms"
        case .quads: return "Quads"
        case .hamstrings: return "Hamstrings"
        case .glutes: return "Glutes"
        case .calves: return "Calves"
        case .core: return "Core"
        case .obliques: return "Obliques"
        case .neck: return "Neck"
        case .wrists: return "Wrists"
        case .feet: return "Feet"
        case .ankles: return "Ankles"
        case .fullBody: return "Full body"
        }
    }
}

extension MuscleGroup {
    /// Secondary muscles for a lift whose primary is this group — the
    /// shared synergist table, and the ONE place it lives. The body
    /// diagram lights them, recovery counts them as trained, and
    /// rest-day stretches cover them, all through
    /// `LibraryExercise.trainedMuscles` — so the five surfaces can
    /// never disagree about what an exercise works. Only real
    /// synergists: a bench press works shoulders and triceps with the
    /// chest; a lateral raise works delts alone. An exercise whose
    /// entry sets an explicit `secondaryMuscles` list overrides this
    /// default (chest fly, lateral raise, face pull).
    static func synergists(for primary: MuscleGroup) -> [MuscleGroup] {
        switch primary {
        case .chest: return [.shoulders, .triceps]
        case .back: return [.biceps, .forearms]
        case .shoulders: return [.triceps]
        case .biceps: return [.forearms]
        case .triceps: return []
        case .forearms: return [.biceps]
        case .neck: return []
        case .wrists: return []
        case .feet: return []
        case .ankles: return []
        case .quads: return [.glutes, .hamstrings]
        case .hamstrings: return [.glutes]
        case .glutes: return [.hamstrings, .quads]
        case .calves: return []
        case .core: return [.obliques]
        case .obliques: return [.core]
        case .fullBody: return [.chest, .back, .shoulders, .quads, .glutes, .core]
        }
    }
}

// MARK: - Library exercise

/// One exercise in the library. The generator turns it into an
/// ExerciseTemplate with goal-appropriate sets/reps and an
/// experience-appropriate starting weight.
struct LibraryExercise: Identifiable, Codable, Equatable {
    var id: String
    var name: String
    var muscle: MuscleGroup
    var equipment: Set<Equipment>
    var substitutes: [String]
    var defaultSets: Int
    var repRange: String
    var topReps: Int
    var isPair: Bool
    var isCompound: Bool
    var cues: String?
    var newWeightLb: Double?
    var someWeightLb: Double?
    var experiencedWeightLb: Double?
    /// False for movements that are not working sets (stretches) — the
    /// single source of truth for hypertrophy suitability, so the library
    /// filter, the generator, and the quiz all agree. True by default:
    /// every working exercise in the library is a hypertrophy-suitable
    /// movement when taken close to failure.
    var hypertrophySuitable: Bool = true
    /// Muscles this exercise works beyond its primary (real synergists
    /// only). Nil = the shared default for the primary group
    /// (`MuscleGroup.synergists`) — an explicit list overrides it, so a
    /// chest fly (chest isolation) trains chest only while a bench
    /// press trains chest + shoulders + triceps. Nil by default, so
    /// the 1,583 literals need no per-entry flag — and so older saved
    /// JSON without the key still decodes.
    var secondaryMuscles: [MuscleGroup]? = nil

    init(
        id: String, name: String, muscle: MuscleGroup, equipment: Set<Equipment>,
        substitutes: [String] = [], defaultSets: Int = 3, repRange: String = "8–12",
        topReps: Int = 12, isPair: Bool = false, isCompound: Bool = false,
        cues: String? = nil, newWeightLb: Double? = nil, someWeightLb: Double? = nil,
        experiencedWeightLb: Double? = nil, secondaryMuscles: [MuscleGroup]? = nil,
        hypertrophySuitable: Bool = true
    ) {
        self.id = id
        self.name = name
        self.muscle = muscle
        self.equipment = equipment
        self.substitutes = substitutes
        self.defaultSets = defaultSets
        self.repRange = repRange
        self.topReps = topReps
        self.isPair = isPair
        self.isCompound = isCompound
        self.cues = cues
        self.newWeightLb = newWeightLb
        self.someWeightLb = someWeightLb
        self.experiencedWeightLb = experiencedWeightLb
        self.secondaryMuscles = secondaryMuscles
        self.hypertrophySuitable = hypertrophySuitable
    }

    /// Primary + secondary muscles, in order — the muscles every
    /// surface agrees this exercise trains. The body diagram lights
    /// these, recovery counts these as trained, and rest-day stretches
    /// cover these. Set/volume counts stay primary-only (one set is
    /// one set — see `WorkoutStore.setsByMuscleThisWeek`).
    var trainedMuscles: [MuscleGroup] {
        [muscle] + (secondaryMuscles ?? MuscleGroup.synergists(for: muscle))
    }

    func startingWeight(for experience: ExperienceLevel) -> Double? {
        switch experience {
        case .new: return newWeightLb
        case .some: return someWeightLb
        case .experienced: return experiencedWeightLb
        }
    }

    /// Equipment that adds external load. Everything else (bench, pull-up
    /// bar, squat rack, suspension straps) is support, not load.
    static let loadedEquipment: Set<Equipment> = [
        .barbell, .dumbbell, .cable, .machine, .kettlebell, .smithMachine,
        .ezBar, .trapBar, .landmine, .bands, .medicineBall, .weightPlates,
    ]

    /// True when this is a bodyweight exercise: it uses bodyweight and no
    /// loaded equipment (a pull-up is [.bodyweight, .pullUpBar]; a dumbbell
    /// calf raise is [.bodyweight, .dumbbell] and is weighted). Computed
    /// from equipment so the 1,597 literals need no per-entry flag — and
    /// so it can never disagree with the equipment list. History and
    /// Calendar render "Bodyweight × reps" for nil weights off this flag.
    var isBodyweight: Bool {
        equipment.contains(.bodyweight) && equipment.isDisjoint(with: Self.loadedEquipment)
    }

    /// Bottom of the rep range, parsed from repRange ("8–12" -> 8).
    var bottomReps: Int { GymTracker.bottomReps(forRepRange: repRange, topReps: topReps) }

    /// Convert a user-created exercise into a library entry so the generator
    /// and the swap picker can use it like any built-in.
    init(from custom: CustomExercise) {
        self.init(
            id: custom.id, name: custom.name, muscle: custom.muscle,
            equipment: custom.equipment, substitutes: [],
            defaultSets: custom.defaultSets, repRange: custom.repRange,
            topReps: custom.topReps, isPair: custom.isPair, isCompound: false,
            cues: custom.cues,
            newWeightLb: custom.someWeightLb, someWeightLb: custom.someWeightLb,
            experiencedWeightLb: custom.someWeightLb
        )
    }
}

// MARK: - The library (1635 exercises)

enum ExerciseLibrary {
    /// Id → exercise, built once: a linear scan of 1,635 entries per
    /// lookup froze the Strength graph with years of history.
    private static let index: [String: LibraryExercise] =
        Dictionary(all.map { ($0.id, $0) }, uniquingKeysWith: { first, _ in first })

    static func byId(_ id: String) -> LibraryExercise? {
        index[id]
    }

    /// Look up an exercise including user-created customs.
    static func byId(_ id: String, plus customs: [CustomExercise]) -> LibraryExercise? {
        if let lib = index[id] { return lib }
        return customs.first(where: { $0.id == id }).map { LibraryExercise(from: $0) }
    }

    /// The full exercise pool: built-ins + the user's customs.
    static func all(plus customs: [CustomExercise]) -> [LibraryExercise] {
        all + customs.map { LibraryExercise(from: $0) }
    }

    static let all: [LibraryExercise] = [
        // Chest
        LibraryExercise(id: "barbell-bench", name: "Barbell Bench Press", muscle: .chest,
            equipment: [.barbell, .bench], substitutes: ["dumbbell-bench", "push-up", "chest-press-machine"],
            isCompound: true, cues: "Bar touches mid-chest, feet planted.",
            newWeightLb: nil, someWeightLb: 95, experiencedWeightLb: 135),
