            repRange: "12–15", topReps: 15, cues: "Walk a straight line, heel to toe."),
        // Stretches (added 2026-11-10): gentle static stretches, one per
        // major muscle group, so the rest-day "Stretches to try" section
        // in TodayView can match them by name ("Stretch") and muscle.
        // Bodyweight-only, no weights, no loaded or ballistic moves.
        // Ids start with "stretch-" so they sort late in the generator's
        // per-muscle pools and are never a preferred pick for program days.
        LibraryExercise(id: "stretch-lat", name: "Lat Stretch", muscle: .back,
            equipment: [.bodyweight], substitutes: ["stretch-upper-back", "stretch-chest"],
            defaultSets: 2, repRange: "20–30 sec", topReps: 30, isPair: true,
            cues: "Hold a post or door frame overhead with one hand and lean away until you feel a gentle pull along the side of your back. Hold 20–30 seconds each side. Keep breathing, don't bounce.",
            hypertrophySuitable: false),
        LibraryExercise(id: "stretch-upper-back", name: "Upper Back Stretch", muscle: .back,
            equipment: [.bodyweight], substitutes: ["stretch-lat", "stretch-chest"],
            defaultSets: 2, repRange: "20–30 sec", topReps: 30,
            cues: "Clasp your hands in front of you, round your upper back and reach forward. Hold 20–30 seconds. You should feel a gentle pull between your shoulder blades.",
            hypertrophySuitable: false),
        LibraryExercise(id: "stretch-biceps", name: "Biceps Stretch", muscle: .biceps,
            equipment: [.bodyweight], substitutes: ["stretch-triceps", "stretch-chest"],
            defaultSets: 2, repRange: "20–30 sec", topReps: 30, isPair: true,
            cues: "Stand sideways to a wall, place your palm flat on it behind you with fingers pointing back. Turn gently away until you feel a light pull in the front of your upper arm. Hold 20–30 seconds each side.",
            hypertrophySuitable: false),
        LibraryExercise(id: "stretch-rear-delt", name: "Rear Delt Stretch", muscle: .shoulders,
            equipment: [.bodyweight], substitutes: ["stretch-shoulder", "stretch-upper-back"],
            defaultSets: 2, repRange: "20–30 sec", topReps: 30, isPair: true,
            cues: "Bring one arm across your chest and hold it near the elbow with the other hand. Keep your shoulder down and relaxed. Hold 20–30 seconds each side. You should feel a gentle pull at the back of your shoulder.",
            hypertrophySuitable: false),
        LibraryExercise(id: "stretch-chest", name: "Chest Stretch", muscle: .chest,
            equipment: [.bodyweight], substitutes: ["stretch-biceps", "stretch-shoulder"],
            defaultSets: 2, repRange: "20–30 sec", topReps: 30,
            cues: "Stand in a doorway, place a forearm on the frame with your elbow near shoulder height. Step forward gently until you feel a light pull across your chest. Hold 20–30 seconds.",
            hypertrophySuitable: false),
        LibraryExercise(id: "stretch-shoulder", name: "Overhead Shoulder Stretch", muscle: .shoulders,
            equipment: [.bodyweight], substitutes: ["stretch-rear-delt", "stretch-triceps"],
            defaultSets: 2, repRange: "20–30 sec", topReps: 30,
            cues: "Raise both arms overhead and hold your opposite elbows. Lean gently to one side, then the other. Hold 20–30 seconds each side. Keep your ribs down and breathe steadily.",
            hypertrophySuitable: false),
        LibraryExercise(id: "stretch-quad", name: "Quad Stretch", muscle: .quads,
            equipment: [.bodyweight], substitutes: ["stretch-hamstring", "stretch-glute"],
            defaultSets: 2, repRange: "20–30 sec", topReps: 30, isPair: true,
            cues: "Stand tall, hold a wall for balance, bend one knee and hold that foot behind you. Keep your knees close together. Hold 20–30 seconds each side. You should feel a gentle pull in the front of your thigh.",
            hypertrophySuitable: false),
        LibraryExercise(id: "stretch-hamstring", name: "Hamstring Stretch", muscle: .hamstrings,
            equipment: [.bodyweight], substitutes: ["stretch-quad", "stretch-glute"],
            defaultSets: 2, repRange: "20–30 sec", topReps: 30, isPair: true,
            cues: "Put one heel on a low step, keep that leg straight with a soft knee. Hinge forward from your hips with a straight back until you feel a gentle pull behind your thigh. Hold 20–30 seconds each side.",
            hypertrophySuitable: false),
        LibraryExercise(id: "stretch-glute", name: "Glute Stretch", muscle: .glutes,
            equipment: [.bodyweight], substitutes: ["stretch-hamstring", "stretch-quad"],
            defaultSets: 2, repRange: "20–30 sec", topReps: 30, isPair: true,
            cues: "Sit and cross one ankle over the opposite knee, sit tall and lean forward slightly. Hold 20–30 seconds each side. You should feel a gentle pull in the hip of the crossed leg.",
            hypertrophySuitable: false),
        LibraryExercise(id: "stretch-calf", name: "Calf Stretch", muscle: .calves,
            equipment: [.bodyweight], substitutes: ["stretch-hamstring", "stretch-quad"],
            defaultSets: 2, repRange: "20–30 sec", topReps: 30, isPair: true,
            cues: "Face a wall, step one foot back and press that heel into the floor with the leg straight. Hold 20–30 seconds each side. You should feel a gentle pull in the back of your lower leg.",
            hypertrophySuitable: false),
        LibraryExercise(id: "stretch-core", name: "Cobra Stretch", muscle: .core,
            equipment: [.bodyweight], substitutes: ["stretch-chest", "stretch-upper-back"],
            defaultSets: 2, repRange: "20–30 sec", topReps: 30,
            cues: "Lie face down, hands under your shoulders, and press your chest up gently while your hips stay on the floor. Keep your elbows soft. Hold 20–30 seconds. Only rise as far as feels comfortable.",
            hypertrophySuitable: false),
        LibraryExercise(id: "stretch-triceps", name: "Triceps Stretch", muscle: .triceps,
            equipment: [.bodyweight], substitutes: ["stretch-biceps", "stretch-shoulder"],
            defaultSets: 2, repRange: "20–30 sec", topReps: 30, isPair: true,
            cues: "Raise one arm overhead, bend the elbow so your hand rests down your upper back. Use the other hand to gently hold the elbow. Hold 20–30 seconds each side. You should feel a gentle pull in the back of your upper arm.",
            hypertrophySuitable: false),
    ]
}

// MARK: - Limit rules (the feature no competitor has)

/// Which exercises a limit rules out, and what replaces them. Generalized
/// from DaRon's own shoulder story: no overhead press, no incline press —
/// cable fly and face pulls instead.
enum LimitRules {
    static func excludedExerciseIds(for limit: Limit) -> Set<String> {
        switch limit {
        case .shoulder:
            return ["overhead-press", "barbell-ohp", "machine-shoulder-press",
                    "incline-bench", "incline-barbell-bench", "dips", "upright-row",
                    "arnold-press", "band-overhead-press", "barbell-push-press",
                    "dumbbell-push-press", "dumbbell-shoulder-press-standing",
                    "kettlebell-press", "kettlebell-push-press", "landmine-press",
                    "z-press", "cable-shoulder-press", "barbell-clean-and-press",
                    "dumbbell-clean-and-press", "kettlebell-clean-and-press",
                    "seated-barbell-ohp", "incline-chest-press-machine",
                    "smith-incline-bench", "bench-dip", "weighted-bench-dip",
                    "dumbbell-upright-row", "kettlebell-upright-row",
                    "cable-upright-row", "overhead-squat", "dumbbell-lunge-to-press"]
        case .lowerBack:
            return ["deadlift", "romanian-deadlift", "barbell-row",
                    "good-morning", "kettlebell-swing",
                    "deficit-deadlift", "dumbbell-deadlift",
                    "dumbbell-romanian-deadlift", "dumbbell-stiff-leg-deadlift",
                    "dumbbell-sumo-deadlift", "kettlebell-deadlift",
                    "kettlebell-romanian-deadlift", "kettlebell-stiff-leg-deadlift",
                    "single-leg-romanian-deadlift", "snatch-grip-deadlift",
                    "stiff-leg-deadlift", "sumo-deadlift", "trap-bar-deadlift",
                    "band-good-morning", "dumbbell-good-morning",
                    "seated-good-morning", "pendlay-row", "yates-row",
                    "t-bar-row", "seal-row", "landmine-row",
                    "kettlebell-swing-single-arm", "dumbbell-swing"]
        case .knee:
            return ["squat", "leg-extension", "hack-squat", "step-up",
                    "barbell-hack-squat", "barbell-sumo-squat", "belt-squat",
                    "bodyweight-squat", "box-squat", "dumbbell-front-squat",
                    "dumbbell-squat", "dumbbell-sumo-squat", "front-squat",
                    "jump-squat", "kettlebell-squat", "landmine-squat",
