    static func substitute(for id: String, limit: Limit) -> String? {
        switch limit {
        case .shoulder:
            switch id {
            case "overhead-press", "barbell-ohp", "machine-shoulder-press", "upright-row",
                 "arnold-press", "band-overhead-press", "barbell-push-press",
                 "dumbbell-push-press", "dumbbell-shoulder-press-standing",
                 "kettlebell-press", "kettlebell-push-press", "landmine-press",
                 "z-press", "cable-shoulder-press", "barbell-clean-and-press",
                 "dumbbell-clean-and-press", "kettlebell-clean-and-press",
                 "seated-barbell-ohp", "dumbbell-upright-row",
                 "kettlebell-upright-row", "cable-upright-row",
                 "overhead-squat", "dumbbell-lunge-to-press":
                return "lateral-raise"
            case "incline-bench", "incline-barbell-bench", "incline-chest-press-machine",
                 "smith-incline-bench":
                return "chest-fly"
            case "dips", "bench-dip", "weighted-bench-dip":
                return "triceps-pushdown"
            default:
                return nil
            }
        case .lowerBack:
            switch id {
            case "deadlift", "romanian-deadlift", "good-morning", "kettlebell-swing",
                 "deficit-deadlift", "dumbbell-deadlift", "dumbbell-romanian-deadlift",
                 "dumbbell-stiff-leg-deadlift", "dumbbell-sumo-deadlift",
                 "kettlebell-deadlift", "kettlebell-romanian-deadlift",
                 "kettlebell-stiff-leg-deadlift", "single-leg-romanian-deadlift",
                 "snatch-grip-deadlift", "stiff-leg-deadlift", "sumo-deadlift",
                 "trap-bar-deadlift", "band-good-morning", "dumbbell-good-morning",
                 "seated-good-morning", "kettlebell-swing-single-arm", "dumbbell-swing":
                return "hip-thrust"
            case "barbell-row", "pendlay-row", "yates-row", "t-bar-row",
                 "seal-row", "landmine-row":
                return "cable-row"
            default:
                return nil
            }
        case .knee:
            switch id {
            case "squat", "leg-extension", "hack-squat",
                 "barbell-hack-squat", "barbell-sumo-squat", "belt-squat",
                 "bodyweight-squat", "box-squat", "dumbbell-front-squat",
                 "dumbbell-squat", "dumbbell-sumo-squat", "front-squat",
                 "jump-squat", "kettlebell-squat", "landmine-squat",
                 "overhead-squat", "pause-squat", "pendulum-squat",
                 "pistol-squat", "sissy-squat", "smith-machine-squat",
                 "spanish-squat", "v-squat-machine", "zercher-squat":
                return "leg-press"
            case "step-up", "barbell-step-up",
                 "barbell-lunge", "dumbbell-lunge", "dumbbell-reverse-lunge",
                 "dumbbell-walking-lunge", "forward-lunge", "reverse-lunge",
                 "walking-lunge", "jumping-lunge", "lateral-lunge", "curtsy-lunge",
                 "dumbbell-lunge-to-press", "barbell-split-squat",
                 "dumbbell-split-squat", "smith-machine-split-squat":
                return "split-squat"
            default:
                return nil
            }
        case .neck:
            switch id {
            case "overhead-press", "barbell-ohp", "machine-shoulder-press", "upright-row",
                 "arnold-press", "band-overhead-press", "barbell-push-press",
                 "dumbbell-push-press", "dumbbell-shoulder-press-standing",
                 "kettlebell-press", "kettlebell-push-press", "landmine-press",
                 "z-press", "cable-shoulder-press", "barbell-clean-and-press",
                 "dumbbell-clean-and-press", "kettlebell-clean-and-press",
                 "seated-barbell-ohp", "dumbbell-upright-row",
                 "kettlebell-upright-row", "cable-upright-row",
                 "overhead-squat", "dumbbell-lunge-to-press":
                return "lateral-raise"
            case "neck-flexion", "neck-extension", "neck-lateral-flexion", "neck-rotation",
                 "band-neck-flexion", "band-neck-extension", "band-neck-lateral-flexion",
                 "isometric-neck-hold", "chin-tuck", "plate-neck-flexion":
                return "lateral-raise"
            default:
                return nil
            }
        case .elbow:
            switch id {
            case "overhead-extension", "skullcrusher", "dips", "close-grip-bench",
                 "jm-press", "dumbbell-tate-press", "bench-dip", "weighted-bench-dip":
                return "triceps-pushdown"
            case "preacher-curl", "reverse-curl":
                return "hammer-curl"
            default:
                return nil
            }
        case .wrist:
            switch id {
            case "push-up", "barbell-bench":
                return "chest-press-machine"
            case "plank":
                return "dead-bug"
            case "barbell-ohp":
                return "lateral-raise"
            case "dumbbell-wrist-curl", "reverse-curl":
                return "hammer-curl"
            case "barbell-wrist-curl", "cable-wrist-curl", "dumbbell-reverse-wrist-curl",
                 "barbell-reverse-wrist-curl", "behind-back-wrist-curl",
                 "dumbbell-wrist-rotation", "cable-wrist-curl-palm-up",
                 "dumbbell-wrist-curl-tempo", "dumbbell-wrist-curl-paused",
                 "dumbbell-wrist-curl-single-arm", "dumbbell-wrist-curl-behind-back",
                 "barbell-wrist-curl-tempo", "barbell-wrist-curl-seated",
                 "barbell-wrist-curl-behind-back-tempo",
                 "barbell-reverse-wrist-curl-tempo", "barbell-reverse-wrist-curl-seated",
                 "cable-wrist-curl-tempo", "cable-wrist-curl-single-arm",
                 "cable-reverse-wrist-curl", "cable-reverse-wrist-curl-single-arm",
                 "ez-bar-wrist-curl", "ez-bar-reverse-wrist-curl",
                 "wrist-curl-band", "reverse-wrist-curl-band",
                 "wrist-curl-kettlebell", "wrist-curl-plate",
                 "dumbbell-wrist-rotation-tempo", "dumbbell-wrist-rotation-single-arm",
                 "barbell-wrist-rotation", "wrist-roller", "wrist-roller-reverse",
                 "plate-pinch-hold", "gripper-squeeze", "gripper-hold",
                 "rice-bucket-squeeze", "rice-bucket-extension",
                 "finger-curl-dumbbell", "finger-curl-barbell", "finger-extension-band",
                 "dumbbell-radial-deviation", "dumbbell-ulnar-deviation",
                 "band-wrist-extension", "dumbbell-wrist-extension",
                 "wrist-circles", "wrist-extension-machine":
                return "hammer-curl"
            default:
                return nil
            }
        case .upperBack:
            switch id {
            case "barbell-row", "dumbbell-pullover", "straight-arm-pulldown",
                 "pendlay-row", "yates-row", "t-bar-row", "seal-row",
                 "landmine-row", "cable-pullover":
                return "cable-row"
            case "deadlift", "deficit-deadlift", "dumbbell-deadlift",
                 "dumbbell-romanian-deadlift", "dumbbell-stiff-leg-deadlift",
                 "dumbbell-sumo-deadlift", "kettlebell-deadlift",
                 "kettlebell-romanian-deadlift", "kettlebell-stiff-leg-deadlift",
                 "single-leg-romanian-deadlift", "snatch-grip-deadlift",
                 "stiff-leg-deadlift", "sumo-deadlift", "trap-bar-deadlift":
                return "hip-thrust"
            default:
                return nil
            }
        case .hip:
            switch id {
            case "squat", "goblet-squat", "split-squat", "step-up",
                 "barbell-hack-squat", "barbell-sumo-squat", "belt-squat",
                 "bodyweight-squat", "box-squat", "dumbbell-front-squat",
                 "dumbbell-squat", "dumbbell-sumo-squat", "front-squat",
                 "jump-squat", "kettlebell-squat", "landmine-squat",
                 "overhead-squat", "pause-squat", "pendulum-squat",
                 "pistol-squat", "sissy-squat", "smith-machine-squat",
                 "spanish-squat", "v-squat-machine", "zercher-squat",
                 "barbell-step-up", "barbell-lunge", "dumbbell-lunge",
                 "dumbbell-reverse-lunge", "dumbbell-walking-lunge",
                 "forward-lunge", "reverse-lunge", "walking-lunge",
                 "jumping-lunge", "lateral-lunge", "curtsy-lunge",
                 "dumbbell-lunge-to-press", "barbell-split-squat",
                 "dumbbell-split-squat", "smith-machine-split-squat":
                return "leg-press"
            case "hip-thrust":
                return "leg-curl"
            default:
                return nil
            }
        case .ankle:
            switch id {
            case "squat", "goblet-squat", "split-squat", "step-up", "hack-squat",
                 "barbell-hack-squat", "barbell-sumo-squat", "belt-squat",
                 "bodyweight-squat", "box-squat", "dumbbell-front-squat",
                 "dumbbell-squat", "dumbbell-sumo-squat", "front-squat",
                 "jump-squat", "kettlebell-squat", "landmine-squat",
                 "overhead-squat", "pause-squat", "pendulum-squat",
                 "pistol-squat", "sissy-squat", "smith-machine-squat",
                 "spanish-squat", "v-squat-machine", "zercher-squat",
                 "barbell-step-up", "barbell-lunge", "dumbbell-lunge",
                 "dumbbell-reverse-lunge", "dumbbell-walking-lunge",
                 "forward-lunge", "reverse-lunge", "walking-lunge",
                 "jumping-lunge", "lateral-lunge", "curtsy-lunge",
                 "dumbbell-lunge-to-press", "barbell-split-squat",
                 "dumbbell-split-squat", "smith-machine-split-squat":
                return "leg-press"
            case "calf-raise", "seated-calf-raise", "single-leg-calf-raise",
                 "hack-squat-calf-raise", "leg-press-calf-raise",
                 "tibialis-raise", "dumbbell-tibialis-raise", "tibialis-raise-tempo",
                 "tibialis-raise-banded", "tibialis-raise-cable", "tibialis-raise-single-leg",
                 "tibialis-raise-wall", "tibialis-raise-kettlebell", "heel-walk",
                 "band-ankle-inversion", "band-ankle-eversion", "ankle-circles",
                 "ankle-alphabet", "band-ankle-dorsiflexion", "band-ankle-plantarflexion",
                 "single-leg-balance", "heel-to-toe-walk",
                 "toe-raise", "toe-raise-seated", "toe-raise-standing", "toe-walk",
                 "toe-curl", "towel-scrunch", "marble-pickup", "toe-spread",
                 "short-foot", "barefoot-balance", "toe-yoga", "foot-rolling":
                return "leg-curl"
            default:
                return nil
            }
        case .chest:
            switch id {
            case "barbell-bench", "dumbbell-bench", "incline-bench", "incline-barbell-bench",
                 "decline-bench", "chest-fly", "dumbbell-fly", "push-up",
                 "chest-press-machine",
                 "decline-barbell-bench", "band-chest-press", "cable-chest-press",
                 "decline-chest-press-machine", "incline-chest-press-machine",
                 "smith-incline-bench", "smith-machine-bench", "pause-bench-press",
                 "spoto-press", "dumbbell-floor-press", "barbell-floor-press",
                 "kettlebell-floor-press", "dumbbell-squeeze-press", "hex-press",
                 "svend-press", "flat-bench", "single-arm-dumbbell-press":
                return "lateral-raise"
            case "dips", "close-grip-bench", "bench-dip", "weighted-bench-dip":
                return "triceps-pushdown"
            default:
                return nil
            }
        case .core:
            switch id {
            case "plank", "cable-crunch", "hanging-leg-raise", "dead-bug", "russian-twist",
                 "side-plank", "cable-woodchop", "pallof-press",
                 "band-pallof-press", "cable-pallof-press":
                return "glute-bridge"
            default:
                return nil
            }
        case .other:
            return nil
        }
    }
}

// MARK: - Program generator (rules-based, on-device, no server)

/// Builds a program from the user's quiz answers. Every answer visibly
/// changes the result: split from days/week, exercise pool from equipment,
/// swaps from limits, rep ranges from goal, starting weights from experience.
enum ProgramGenerator {

    static func generate(profile: UserProfile) -> UserProgram {
        generate(profile: profile, customExercises: [], preferences: [:], equipment: nil)
    }

    /// Generate a program. `customExercises` and `preferences` come from the
    /// store; `equipment` overrides the profile's have-set (an active Gym
    /// Profile's checklist). The finisher is generated from the same pool —
    /// it never names equipment the user doesn't have.
    static func generate(profile: UserProfile, customExercises: [CustomExercise],
                         preferences: [String: ExercisePreference],
                         equipment: Set<Equipment>? = nil) -> UserProgram {
        let builder = Builder(profile: profile, customExercises: customExercises,
                              preferences: preferences, equipmentOverride: equipment)
        let days = buildDays(builder: builder, profile: profile)
        let splitName = splitName(for: profile.daysPerWeek)
        return UserProgram(
            id: UUID().uuidString,
            name: "Your \(profile.daysPerWeek)-Day \(splitName) Plan",
            days: days,
            swaps: builder.swaps,
            isPreset: false
        )
    }

    static func splitName(for daysPerWeek: Int) -> String {
        switch daysPerWeek {
        case 1, 3: return "Full Body"
        case 2, 4: return "Upper/Lower"
        case 5, 6, 7: return "Push/Pull/Legs"
        default: return "Full Body"
        }
    }

    /// Build a template for a library exercise with the profile's goal and
    /// experience. Used by the generator and by the plan reveal's swap picker.
    /// Rest follows the goal and the load: hypertrophy (Build muscle) rests
    /// 60–90 s (90 s compounds, 60 s isolations — the NSCA hypertrophy
    /// band); other goals keep the longer compound rest (2.5 min) so the
    /// next set holds its weight. The user can still override either per
    /// exercise in Today → Options.
    static func template(for lib: LibraryExercise, profile: UserProfile) -> ExerciseTemplate {
        let (sets, repRange, topReps): (Int, String, Int)
        switch profile.goal {
        case .buildMuscle:
            (sets, repRange, topReps) = (lib.defaultSets, lib.repRange, lib.topReps)
        case .getStronger:
            if lib.isCompound { (sets, repRange, topReps) = (4, "4–6", 6) }
            else { (sets, repRange, topReps) = (3, "8–12", 12) }
        case .getLean:
            // Leanness is an energy-balance outcome, not a rep-range
            // outcome — so compounds stay in the 6–12 strength/hypertrophy
            // range (high-rep deadlifts and squats are a form-breakdown
            // risk) and only isolations use 10–15, with the conditioning
            // finisher doing the conditioning work.
            if lib.isCompound { (sets, repRange, topReps) = (3, "6–12", 12) }
            else { (sets, repRange, topReps) = (3, "10–15", 15) }
        case .stayConsistent:
            (sets, repRange, topReps) = (2, "8–12", 12)
        }
        let restSeconds: TimeInterval
        if profile.goal == .buildMuscle {
            restSeconds = lib.isCompound ? 90 : 60
        } else {
            restSeconds = lib.isCompound ? 150 : 90
        }
        return ExerciseTemplate(
            id: lib.id, name: lib.name, sets: sets, repRange: repRange, topReps: topReps,
            defaultWeightLb: lib.startingWeight(for: profile.experience),
            isPair: lib.isPair, weightNote: nil, cues: lib.cues,
            restSeconds: restSeconds,
            isBodyweight: lib.isBodyweight
        )
    }

    private static func buildDays(builder: Builder, profile: UserProfile) -> [DayPlan] {
        switch profile.daysPerWeek {
        case 1:
            // One session: a single full-body day.
            return [
                builder.fullBodyDay(key: "Mon", weekday: "Monday", letter: "A"),
            ]
        case 2:
            // Upper / lower — each half of the body once a week.
            return [
                builder.upperDay(key: "Mon", weekday: "Monday"),
                builder.lowerDay(key: "Thu", weekday: "Thursday"),
            ]
        case 3:
            return [
                builder.fullBodyDay(key: "Mon", weekday: "Monday", letter: "A"),
                builder.fullBodyDay(key: "Wed", weekday: "Wednesday", letter: "B"),
                builder.fullBodyDay(key: "Fri", weekday: "Friday", letter: "C"),
            ]
        case 4:
            return [
                builder.upperDay(key: "Mon", weekday: "Monday"),
                builder.lowerDay(key: "Tue", weekday: "Tuesday"),
                builder.upperDay(key: "Thu", weekday: "Thursday"),
                builder.lowerDay(key: "Fri", weekday: "Friday"),
            ]
        case 6:
            // Push / pull / legs, twice a week. Sunday rests.
            return [
                builder.pushDay(key: "Mon", weekday: "Monday"),
                builder.pullDay(key: "Tue", weekday: "Tuesday"),
                builder.legsDay(key: "Wed", weekday: "Wednesday"),
                builder.pushDay(key: "Thu", weekday: "Thursday"),
                builder.pullDay(key: "Fri", weekday: "Friday"),
                builder.legsDay(key: "Sat", weekday: "Saturday"),
            ]
        case 7:
            // Push / pull / legs, twice a week, plus a light arms-and-core
            // day on Sunday. No muscle is trained hard every day: each
            // major muscle gets two hard sessions with rest days between,
            // and Sunday is small muscles (arms, core, calves) that
            // recover fast and were only hit lightly during the week.
            return [
                builder.pushDay(key: "Mon", weekday: "Monday"),
                builder.pullDay(key: "Tue", weekday: "Tuesday"),
                builder.legsDay(key: "Wed", weekday: "Wednesday"),
                builder.pushDay(key: "Thu", weekday: "Thursday"),
                builder.pullDay(key: "Fri", weekday: "Friday"),
                builder.legsDay(key: "Sat", weekday: "Saturday"),
                builder.armsCoreDay(key: "Sun", weekday: "Sunday"),
            ]
        default: // 5 days — push / pull / legs + upper mix (DaRon's split shape)
            return [
                builder.legsDay(key: "Mon", weekday: "Monday"),
                builder.pushDay(key: "Tue", weekday: "Tuesday"),
                builder.legsDay(key: "Wed", weekday: "Wednesday"),
                builder.pullDay(key: "Thu", weekday: "Thursday"),
                builder.upperMixDay(key: "Fri", weekday: "Friday"),
            ]
        }
    }

    // MARK: - Builder

    private final class Builder {
        let profile: UserProfile
        var swaps: [ProgramSwap] = []
        private let available: Set<Equipment>
        private let customs: [CustomExercise]
        private let preferences: [String: ExercisePreference]

        init(profile: UserProfile, customExercises: [CustomExercise] = [],
             preferences: [String: ExercisePreference] = [:],
             equipmentOverride: Set<Equipment>? = nil) {
            self.profile = profile
            self.customs = customExercises
            self.preferences = preferences
            self.available = equipmentOverride ?? profile.equipmentHave
        }

        /// Pick the first preferred exercise the user can do. A limit
        /// exclusion records a swap and uses the limit's substitute; an
        /// equipment gap tries the exercise's own substitutes. Excluded
        /// exercises (Recommend → Exclude) are never picked.
        func pick(_ preferred: [String], muscle: MuscleGroup) -> ExerciseTemplate? {
            // Stretches are never working exercises — the rest-day screen
            // selects them directly from the library. (Same rule as the
            // catalog generator's pick().)
            for id in preferred {
                guard !id.hasPrefix("stretch-") else { continue }
                guard preferences[id] != .exclude else { continue }
                guard let lib = ExerciseLibrary.byId(id, plus: customs) else { continue }
                if let excludedBy = excludedByLimit(lib) {
                    if let subId = LimitRules.substitute(for: lib.id, limit: excludedBy),
                       !subId.hasPrefix("stretch-"),
                       let sub = ExerciseLibrary.byId(subId, plus: customs), isAvailable(sub) {
                        swaps.append(ProgramSwap(from: lib.name, to: sub.name, reason: excludedBy.label))
                        return template(for: sub)
                    }
                    continue
                }
                if isAvailable(lib) {
                    return template(for: lib)
                }
                for subId in lib.substitutes {
                    guard !subId.hasPrefix("stretch-") else { continue }
                    guard let sub = ExerciseLibrary.byId(subId, plus: customs) else { continue }
                    if preferences[sub.id] != .exclude, excludedByLimit(sub) == nil, isAvailable(sub) {
                        return template(for: sub)
                    }
                }
            }
            // Fallback: any available exercise for the muscle. "Recommend more"
            // exercises are tried first.
            let pool = ExerciseLibrary.all(plus: customs).filter {
                $0.muscle == muscle && isAvailable($0) && excludedByLimit($0) == nil
                    && preferences[$0.id] != .exclude && !$0.id.hasPrefix("stretch-")
            }
            if let more = pool.first(where: { preferences[$0.id] == .more }) {
                return template(for: more)
            }
            if let fallback = pool.first {
                return template(for: fallback)
            }
            return nil
        }

        private func isAvailable(_ lib: LibraryExercise) -> Bool {
            lib.equipment.isSubset(of: available)
        }

        private func excludedByLimit(_ lib: LibraryExercise) -> Limit? {
            for limit in profile.limits where LimitRules.excludedExerciseIds(for: limit).contains(lib.id) {
                return limit
            }
            return nil
        }

        private func template(for lib: LibraryExercise) -> ExerciseTemplate {
            ProgramGenerator.template(for: lib, profile: profile)
        }

        // MARK: - Equipment-aware finisher (the fix)
        //
        // The finisher used to be a hardcoded string per day type, so a
        // dumbbells-only user got "Cable chest fly" — equipment they don't
        // have. Now each finisher slot is picked from the same available
        // pool as the main exercises, so it only ever names equipment the
        // user has. Target areas (Leap pattern) get a finisher slot first.

        private struct FinisherSlot {
            var preferred: [String]
            var muscle: MuscleGroup
            var reps: String
        }

        private func finisherItem(preferred: [String], muscle: MuscleGroup, reps: String) -> String? {
            guard let template = pick(preferred, muscle: muscle) else { return nil }
            return "\(template.name) \(reps)"
        }

        private func finisher(slots: [FinisherSlot]) -> [String] {
            var items: [String] = []
            // Target areas first — one light exercise per chosen area.
            for area in profile.targetAreas {
                for muscle in area.muscles {
                    if let item = finisherItem(preferred: preferredForFinisher(muscle: muscle),
                                               muscle: muscle, reps: "2 × 15, light") {
                        items.append(item)
                        break
                    }
                }
                if items.count >= 2 { break }
            }
            for slot in slots {
                if items.count >= 2 { break }
                if let item = finisherItem(preferred: slot.preferred, muscle: slot.muscle, reps: slot.reps) {
                    items.append(item)
                }
            }
            return items
        }

        private func preferredForFinisher(muscle: MuscleGroup) -> [String] {
            switch muscle {
            case .chest: return ["chest-fly", "dumbbell-fly", "push-up"]
            case .back: return ["face-pull", "rear-delt-fly", "band-pull-apart"]
            case .shoulders: return ["lateral-raise", "cable-lateral-raise"]
            case .biceps: return ["dumbbell-curl", "cable-curl", "hammer-curl"]
            case .triceps: return ["triceps-pushdown", "overhead-extension"]
            case .forearms: return ["reverse-curl", "towel-hang", "farmer-hold"]
            case .quads: return ["leg-extension", "goblet-squat", "leg-press"]
            case .hamstrings: return ["leg-curl", "hip-thrust"]
            case .glutes: return ["hip-thrust", "glute-bridge"]
            case .calves: return ["calf-raise", "seated-calf-raise"]
            case .core: return ["plank", "cable-crunch", "dead-bug"]
            case .obliques: return ["russian-twist", "cable-woodchop", "side-plank"]
            case .neck: return ["neck-flexion", "chin-tuck", "neck-extension"]
            case .wrists: return ["dumbbell-wrist-curl", "dumbbell-reverse-wrist-curl", "wrist-curl-band"]
            case .feet: return ["toe-curl", "towel-scrunch", "toe-raise"]
            case .ankles: return ["tibialis-raise", "band-ankle-dorsiflexion", "ankle-circles"]
            case .fullBody: return ["plank", "dead-bug"]
            }
        }

        private func upperFinisher() -> [String] {
            finisher(slots: [
                FinisherSlot(preferred: ["chest-fly", "dumbbell-fly", "push-up"], muscle: .chest, reps: "2 × 15, light"),
                FinisherSlot(preferred: ["triceps-pushdown", "overhead-extension"], muscle: .triceps, reps: "2 × 15, light"),
            ])
        }

        private func lowerFinisher() -> [String] {
            finisher(slots: [
                FinisherSlot(preferred: ["leg-extension", "goblet-squat", "leg-press"], muscle: .quads, reps: "2 × 15, light"),
                FinisherSlot(preferred: ["calf-raise", "seated-calf-raise", "single-leg-calf-raise"], muscle: .calves, reps: "1 × 20, slow"),
            ])
        }

        private func pullFinisher() -> [String] {
            finisher(slots: [
                FinisherSlot(preferred: ["lat-pulldown", "pull-up"], muscle: .back, reps: "2 × 12, light"),
                FinisherSlot(preferred: ["dumbbell-curl", "cable-curl", "hammer-curl"], muscle: .biceps, reps: "2 × 15, light"),
            ])
        }

        // MARK: - Day builders

        private func day(key: String, title: String, subtitle: String,
                         slots: [(preferred: [String], muscle: MuscleGroup)],
                         finisher: [String]) -> DayPlan {
            // Deduplicate: two slots can legitimately pick the same exercise
            // (e.g. a hinge for glutes and one for hamstrings) — a day
            // never lists the same exercise twice.
            var seen: Set<String> = []
            var exercises: [ExerciseTemplate] = []
            for slot in slots {
                guard let template = pick(slot.preferred, muscle: slot.muscle),
                      !seen.contains(template.id) else { continue }
                seen.insert(template.id)
                exercises.append(template)
            }
            return DayPlan(key: key, title: title, subtitle: subtitle,
                           exercises: exercises, finisher: finisher)
        }

        func fullBodyDay(key: String, weekday: String, letter: String) -> DayPlan {
            switch letter {
            case "A":
                return day(key: key, title: "Full Body A",
                           subtitle: "\(weekday) · Squat, press, row, core",
                           slots: [
                            (["squat", "leg-press", "goblet-squat"], .quads),
                            (["dumbbell-bench", "barbell-bench", "push-up"], .chest),
                            (["cable-row", "dumbbell-row", "barbell-row"], .back),
                            (["overhead-press", "lateral-raise"], .shoulders),
                            (["triceps-pushdown", "overhead-extension"], .triceps),
                            (["hip-thrust", "glute-bridge", "barbell-hip-thrust"], .glutes),
                            (["plank", "cable-crunch"], .core),
                           ],
                           finisher: finisher(slots: [
                            FinisherSlot(preferred: ["push-up"], muscle: .chest, reps: "2 × 10"),
                            FinisherSlot(preferred: ["plank", "dead-bug"], muscle: .core, reps: "2 × 30 sec"),
                           ]))
            case "B":
                return day(key: key, title: "Full Body B",
                           subtitle: "\(weekday) · Hinge, pull, press, arms",
                           slots: [
                            (["hip-thrust", "glute-bridge", "barbell-hip-thrust"], .glutes),
                            (["lat-pulldown", "pull-up", "cable-row"], .back),
                            (["overhead-press", "lateral-raise"], .shoulders),
                            (["dumbbell-bench", "barbell-bench", "push-up"], .chest),
                            (["leg-curl", "romanian-deadlift"], .hamstrings),
                            (["dumbbell-curl", "hammer-curl", "cable-curl"], .biceps),
                            (["triceps-pushdown", "overhead-extension"], .triceps),
                           ],
                           finisher: pullFinisher())
            default: // C
                return day(key: key, title: "Full Body C",
                           subtitle: "\(weekday) · Legs, chest, back, calves",
                           slots: [
                            (["leg-press", "squat", "goblet-squat"], .quads),
                            (["chest-fly", "dumbbell-bench", "push-up"], .chest),
                            (["face-pull", "rear-delt-fly", "band-pull-apart"], .back),
                            (["leg-curl", "romanian-deadlift"], .hamstrings),
                            (["calf-raise", "seated-calf-raise"], .calves),
                            (["cable-crunch", "plank"], .core),
                            (["dumbbell-curl", "hammer-curl", "cable-curl"], .biceps),
                            (["triceps-pushdown", "overhead-extension"], .triceps),
                           ],
                           finisher: lowerFinisher())
            }
        }

        func upperDay(key: String, weekday: String) -> DayPlan {
            day(key: key, title: "Upper",
                subtitle: "\(weekday) · Chest, back, shoulders, arms",
                slots: [
                    (["barbell-bench", "dumbbell-bench", "chest-press-machine", "push-up"], .chest),
                    (["cable-row", "barbell-row", "dumbbell-row"], .back),
                    (["overhead-press", "lateral-raise", "machine-shoulder-press"], .shoulders),
                    (["lat-pulldown", "pull-up"], .back),
                    (["dumbbell-curl", "cable-curl", "hammer-curl"], .biceps),
                    (["triceps-pushdown", "overhead-extension", "cable-kickback"], .triceps),
                    (["overhead-extension", "cable-kickback", "band-overhead-extension"], .triceps),
                    (["plank", "cable-crunch", "dead-bug"], .core),
                ],
                finisher: upperFinisher())
        }

        func lowerDay(key: String, weekday: String) -> DayPlan {
            day(key: key, title: "Lower",
                subtitle: "\(weekday) · Quads, glutes, hamstrings, calves",
                slots: [
                    (["squat", "leg-press", "goblet-squat", "split-squat"], .quads),
                    (["hip-thrust", "glute-bridge", "barbell-hip-thrust"], .glutes),
                    (["glute-bridge", "single-leg-glute-bridge", "donkey-kick"], .glutes),
                    (["leg-press", "goblet-squat", "split-squat"], .quads),
                    (["leg-curl", "romanian-deadlift"], .hamstrings),
                    (["romanian-deadlift", "good-morning"], .hamstrings),
                    (["calf-raise", "seated-calf-raise"], .calves),
                    (["seated-calf-raise", "single-leg-calf-raise", "donkey-calf-raise"], .calves),
                ],
                finisher: lowerFinisher())
        }

        func legsDay(key: String, weekday: String) -> DayPlan {
            day(key: key, title: "Legs",
                subtitle: "\(weekday) · Squat, hinge, press, curl, calves",
                slots: [
                    (["squat", "leg-press", "goblet-squat", "split-squat"], .quads),
                    (["hip-thrust", "glute-bridge", "barbell-hip-thrust"], .glutes),
                    (["glute-bridge", "single-leg-glute-bridge", "donkey-kick"], .glutes),
                    (["leg-press", "goblet-squat", "split-squat"], .quads),
                    (["leg-curl", "romanian-deadlift"], .hamstrings),
                    (["romanian-deadlift", "good-morning"], .hamstrings),
                    (["calf-raise", "seated-calf-raise"], .calves),
                    (["seated-calf-raise", "single-leg-calf-raise", "donkey-calf-raise"], .calves),
                ],
                finisher: lowerFinisher())
        }

        func pushDay(key: String, weekday: String) -> DayPlan {
            day(key: key, title: "Push",
                subtitle: "\(weekday) · Chest, shoulders, triceps",
                slots: [
                    (["barbell-bench", "dumbbell-bench", "chest-fly"], .chest),
                    (["incline-bench", "chest-fly", "dumbbell-bench"], .chest),
                    (["overhead-press", "lateral-raise", "machine-shoulder-press"], .shoulders),
                    (["lateral-raise", "cable-lateral-raise"], .shoulders),
                    (["triceps-pushdown", "overhead-extension"], .triceps),
                    (["overhead-extension", "cable-kickback", "band-overhead-extension"], .triceps),
                    (["plank", "cable-crunch", "dead-bug"], .core),
                ],
                finisher: upperFinisher())
        }

        func pullDay(key: String, weekday: String) -> DayPlan {
            day(key: key, title: "Pull",
                subtitle: "\(weekday) · Back, rear delts, biceps",
                slots: [
                    (["lat-pulldown", "pull-up", "cable-row"], .back),
                    (["cable-row", "barbell-row", "dumbbell-row", "seated-row-machine"], .back),
                    (["face-pull", "rear-delt-fly", "band-pull-apart"], .back),
                    (["dumbbell-curl", "cable-curl", "hammer-curl"], .biceps),
                    (["hammer-curl", "dumbbell-curl", "cable-curl"], .biceps),
                    (["plank", "cable-crunch", "dead-bug"], .core),
                ],
                finisher: pullFinisher())
        }

        func upperMixDay(key: String, weekday: String) -> DayPlan {
            day(key: key, title: "Upper Mix",
                subtitle: "\(weekday) · Chest, back, shoulders, arms",
                slots: [
                    (["dumbbell-bench", "barbell-bench", "push-up"], .chest),
                    (["cable-row", "barbell-row", "dumbbell-row"], .back),
                    (["lateral-raise", "overhead-press"], .shoulders),
                    (["chest-fly", "dumbbell-fly", "push-up"], .chest),
                    (["triceps-pushdown", "overhead-extension"], .triceps),
                    (["dumbbell-curl", "hammer-curl", "cable-curl"], .biceps),
                    (["plank", "cable-crunch", "dead-bug"], .core),
                ],
                finisher: upperFinisher())
        }

        /// Light seventh day (7-day split only): arms, core, and calves.
        /// Small muscles that recover fast — a light touch, not a third
        /// heavy session for anything. Keeps the 7-day split from training
        /// any muscle hard every day.
        func armsCoreDay(key: String, weekday: String) -> DayPlan {
            day(key: key, title: "Arms & Core",
                subtitle: "\(weekday) · Light — arms, core, calves",
                slots: [
                    (["dumbbell-curl", "cable-curl", "hammer-curl"], .biceps),
                    (["triceps-pushdown", "overhead-extension"], .triceps),
                    (["plank", "cable-crunch", "dead-bug"], .core),
                    (["calf-raise", "seated-calf-raise"], .calves),
                ],
                finisher: finisher(slots: [
                    FinisherSlot(preferred: ["dumbbell-curl", "cable-curl"], muscle: .biceps, reps: "2 × 15, light"),
                    FinisherSlot(preferred: ["plank", "dead-bug"], muscle: .core, reps: "2 × 30 sec"),
                ]))
        }
    }
}
